sys_variable_value.value:
(function execute(inputs, outputs) {
    var utils = new BillingUtils(inputs.pat_id);

    switch (inputs.mode) {
        case 'total':
            outputs.output = utils.totalAmt().toString();
            break;

        case 'overdue':
            outputs.output = utils.isOverdue(inputs.billing_id) ? 'Overdue' : 'Not Overdue';
            break;

        case 'details':
            var details = utils.billingDetails(inputs.billing_number);
            outputs.output = details ? JSON.stringify(details) : 'Billing record not found';
            break;

        case 'by_patient':
            var records = utils.getBillingRecordsByPatientID();
            outputs.output = records.length > 0 ? JSON.stringify(records) : 'No billing records found';
            break;

        default:
            outputs.output = 'Invalid mode';
    }
})(inputs, outputs);

